const raw = $('WEBHOOK DISPLAY NAME').first().json;
const body = raw.body ?? raw;
const conexao = $input.first().json;

const conexaoId = body.conexaoId || body.conexao_id;
const acao = String(body.acao || body.action || '').toLowerCase();
const displayName = body.display_name || body.displayName || body.nomeExibir || body.novo_nome || null;

if (!conexaoId) throw new Error('Campo conexaoId obrigatorio.');
if (!['solicitar', 'registrar'].includes(acao)) throw new Error('acao deve ser solicitar ou registrar.');
if (!conexao?.access_token || !conexao?.phone_number_id) throw new Error('Conexao nao encontrada ou sem phone_number_id.');
if (!conexao.apiOficial) throw new Error('Conexao nao e API Oficial.');

let pin = body.pin || body.metaPinVerificacao || conexao.metaPinVerificacao || null;
if (pin) pin = String(pin).trim();

let display_name = null;
if (acao === 'solicitar') {
  display_name = String(displayName || '').trim();
  if (!display_name) throw new Error('Campo display_name obrigatorio para solicitar.');
  if (display_name.length > 128) throw new Error('display_name max 128 caracteres.');
}
if (acao === 'registrar' && (!pin || !/^\d{6}$/.test(pin))) {
  throw new Error('PIN obrigatorio (6 digitos). Informe pin no body ou reconecte o numero.');
}

const token = conexao.access_token;
const phoneId = conexao.phone_number_id;
const headers = { Authorization: `Bearer ${token}` };
let numero_registrado = false;

if (acao === 'solicitar') {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v25.0/${phoneId}`,
    qs: { new_display_name: display_name },
    headers,
    json: true
  });
  if (res.error) throw new Error(res.error.error_user_msg || res.error.message || 'Falha ao solicitar display name.');
  if (!res.success) throw new Error('Meta nao confirmou solicitacao de display name.');
}

if (acao === 'registrar') {
  const regRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v25.0/${phoneId}/register`,
    headers: { ...headers, 'Content-Type': 'application/json' },
    body: { messaging_product: 'whatsapp', pin },
    json: true
  });
  if (regRes.error) {
    const code = regRes.error.code;
    const msg = regRes.error.error_user_msg || regRes.error.message || 'Falha ao registrar numero.';
    if (code === 133005) throw new Error('PIN de verificacao em duas etapas incorreto.');
    if (code === 133016) throw new Error('Limite de registros atingido (10 em 72h).');
    throw new Error(msg);
  }
  if (!regRes.success) throw new Error('Meta nao confirmou registro do numero.');
  numero_registrado = true;
}

const phoneRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://graph.facebook.com/v25.0/${phoneId}`,
  qs: { fields: 'verified_name,name_status,new_display_name,new_name_status,status' },
  headers,
  json: true
});
if (phoneRes.error) throw new Error(phoneRes.error.error_user_msg || phoneRes.error.message || 'Falha ao consultar status.');

const LABELS = {
  APPROVED: 'Aprovado',
  AVAILABLE_WITHOUT_REVIEW: 'Disponivel sem revisao',
  DECLINED: 'Recusado',
  EXPIRED: 'Expirado',
  PENDING_REVIEW: 'Em revisao',
  NONE: 'Sem certificado'
};

const now = new Date().toISOString();

return [{
  json: {
    conexaoId,
    syncPayload: {
      metaVerifiedName: phoneRes.verified_name || null,
      metaNameStatus: phoneRes.name_status || null,
      metaNewDisplayName: phoneRes.new_display_name || null,
      metaNewNameStatus: phoneRes.new_name_status || null,
      metaPhoneStatus: phoneRes.status || null,
      metaDadosUpdatedAt: now
    },
    response: {
      ok: true,
      acao,
      conexaoId,
      display_name_solicitado: display_name,
      numero_registrado,
      nome: {
        atual: phoneRes.verified_name || null,
        status: phoneRes.name_status || null,
        statusLabel: LABELS[phoneRes.name_status] || phoneRes.name_status || null,
        novo: phoneRes.new_display_name || null,
        novoStatus: phoneRes.new_name_status || null,
        novoStatusLabel: LABELS[phoneRes.new_name_status] || phoneRes.new_name_status || null
      },
      aviso: acao === 'solicitar'
        ? 'Aguarde aprovacao da Meta. Depois chame acao registrar com o PIN.'
        : 'Numero re-registrado. O display name aprovado passa a valer nos servidores da Meta.'
    }
  }
}];
